do $catchup$
declare
  v_first text;
  v_done int;
  v_step int;
  m record;
begin
  -- Two checks, not one with "or": Postgres resolves every table in a condition before running it.
  if to_regclass('catch_up.state') is null then
    raise exception 'Run part 1 first: it works out what your database is missing. If part 1 said "Nothing to do", you are finished.';
  end if;
  if not exists (select 1 from catch_up.state) then
    raise exception 'Run part 1 first: it works out what your database is missing. If part 1 said "Nothing to do", you are finished.';
  end if;
  select first, done into v_first, v_done from catch_up.state;
  if v_done < 0 then
    raise exception 'Run part % next. Nothing was changed by this part.', v_done + 1;
  end if;
  select coalesce(max(step), 0) into v_step from catch_up.log;
  if v_first is not null then
    for m in select * from (values
    ('0038_apply_form_simplify', $m_0038_apply_form_simplify$
-- 0038_apply_form_simplify.sql
-- Seller application form, simpler and wider:
--   * Maisha Card is accepted as an ID type next to National ID and Passport.
--   * "Year established" is optional, so a seller is not blocked on a detail that is never used to decide.
-- Existing rows are untouched; both changes only widen what the table accepts.
-- Safe to run more than once, and safe whatever the old check constraint was called.

do $$
declare
  c record;
begin
  for c in
    select conname
      from pg_constraint
     where conrelid = 'public.applications'::regclass
       and contype = 'c'
       and pg_get_constraintdef(oid) ilike '%owner_id_type%'
  loop
    execute format('alter table public.applications drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.applications
  add constraint applications_owner_id_type_check
  check (owner_id_type in ('national_id', 'maisha_card', 'passport'));

alter table public.applications
  alter column year_established drop not null;

